let lookup = vec![1, 3, 4, 5, 7, 9, 12].into_iter()
    .into_grouping_map_by(|&n| n % 3)
    .minmax();

assert_eq!(lookup[&0], MinMax(3, 12));
assert_eq!(lookup[&1], MinMax(1, 7));
assert_eq!(lookup[&2], OneElement(5));
assert_eq!(lookup.len(), 3);
```

