3104.docs_markdown:
`.try_collect()` is more convenient way of writing
`.collect::<Result<_, _>>()`

# Example

```
use itertools::Itertools;
use std::{fs, io};

fn process_dir_entries(entries: &[fs::DirEntry]) {
    // ...
    # let _ = entries;
}

fn do_stuff() -> io::Result<()> {
    let entries: Vec<_> = fs::read_dir(".")?.try_collect()?;
    process_dir_entries(&entries);

    Ok(())
}

# let _ = do_stuff;
```

